// [START] Safe & Optimised Persistent Cart Logic
if (isset($_COOKIE['cart_hash'])) {
    $cart_hash = preg_replace('%[^A-Za-z0-9]%', '', $_COOKIE['cart_hash']);
    $current_session = $this->session->getId();

    // Check if user is a guest using the customer object
    $is_guest = !$this->customer->isLogged();

    if ($is_guest && $cart_hash != $current_session && !isset($this->session->data['cart_hash_updated'])) {
        $this->db->query("UPDATE " . DB_PREFIX . "cart SET session_id = '" . $this->db->escape($current_session) . "' WHERE api_id = '0' AND customer_id = '0' AND session_id = '" . $this->db->escape($cart_hash) . "'");

        // Flag to prevent redundant execution
        $this->session->data['cart_hash_updated'] = true;

        $p = $this->get_cookie_params();
        setcookie('cart_hash', $current_session, time() + 86400 * 30, $p['path'], $p['domain'], $p['secure'], true);

        // Update the superglobal immediately so subsequent calls in this lifecycle know it exists
        $_COOKIE['cart_hash'] = $current_session;
    }
}

// 0.1% chance garbage collection to clean up 30-day old abandoned carts
if (rand(1, 1000) === 500) {
    $this->db->query("DELETE FROM " . DB_PREFIX . "cart WHERE (api_id > '0' OR customer_id = '0') AND date_added < DATE_SUB(NOW(), INTERVAL 720 HOUR)");
}
// [END] Safe & Optimised Persistent Cart Logic

private function get_cookie_params() {
  return [
    'secure' => (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off') || (!empty($_SERVER['HTTP_X_FORWARDED_PROTO']) && $_SERVER['HTTP_X_FORWARDED_PROTO'] === 'https'),
    'path'   => !empty(ini_get('session.cookie_path')) ? ini_get('session.cookie_path') : '/',
    'domain' => !empty(ini_get('session.cookie_domain')) ? ini_get('session.cookie_domain') : '',
  ];
}

public function set_cart_cookie() {
  if (!$this->customer->isLogged()) {
      if (!isset($_COOKIE['cart_hash']) || $_COOKIE['cart_hash'] != $this->session->getId()) {
        $p = $this->get_cookie_params();
        setcookie('cart_hash', $this->session->getId(), time() + 86400 * 30, $p['path'], $p['domain'], $p['secure'], true);
        $_COOKIE['cart_hash'] = $this->session->getId();
      }
  }
}
